"""Attribute ratio-revision Top-10 outcomes to EPS denominator and prior price run-up."""
from __future__ import annotations
import argparse,json
from pathlib import Path
import pandas as pd
from experiments.run_market_gated_analyst import revision_breadth_states
FOLDS=(("2017-2019",2017,2019),("2020-2022",2020,2022),("2023-2026",2023,2026))
def summarize(frame,total_active):
 trim=frame[frame.active20<=frame.active20.quantile(.95)] if len(frame) else frame;folds={name:{"count":len(g),"mean_active20":float(g.active20.mean()) if len(g) else None,"win_rate":float((g.active20>0).mean()) if len(g) else None} for name,a,b in FOLDS for g in [frame[frame.signal_date.dt.year.between(a,b)]]};return {"count":len(frame),"months":int(frame.signal_date.nunique()),"revision_median":float(frame.revision.median()) if len(frame) else None,"prior_active20_median":float(frame.prior_active20.median()) if len(frame) else None,"future_active20_mean":float(frame.active20.mean()) if len(frame) else None,"future_active20_median":float(frame.active20.median()) if len(frame) else None,"future_active20_win_rate":float((frame.active20>0).mean()) if len(frame) else None,"trim_best5_mean":float(trim.active20.mean()) if len(trim) else None,"active_sum":float(frame.active20.sum()),"active_sum_share":float(frame.active20.sum()/total_active) if total_active else None,"folds":folds}
def run(signals_path,out_rows,out_json,out_md):
 x=pd.read_csv(signals_path,dtype={"symbol":str});x["signal_date"]=pd.to_datetime(x.signal_date);dates=[d.date().isoformat() for d in sorted(x.signal_date.unique())];states,_=revision_breadth_states(x,dates,"revision");selected=[]
 for day,g in x.groupby("signal_date"):
  key=day.date().isoformat()
  if not states.get(key,False):continue
  positive=g[g.prior_eps.gt(0)];small_cut=float(positive.prior_eps.quantile(.20)) if len(positive) else float("nan");top=g[g.revision.gt(0)].sort_values(["revision","paired_count","symbol"],ascending=[False,False,True]).head(10).copy();negative_deterioration=top.prior_eps.lt(0)&top.current_eps.lt(top.prior_eps);small_positive=top.prior_eps.gt(0)&top.current_eps.gt(top.prior_eps)&top.prior_eps.le(small_cut);normal_positive=top.prior_eps.gt(0)&top.current_eps.gt(top.prior_eps)&~small_positive;top["denominator_category"]="OTHER_RATIO_POSITIVE";top.loc[negative_deterioration,"denominator_category"]="NEGATIVE_BASE_DETERIORATION";top.loc[small_positive,"denominator_category"]="SMALL_POSITIVE_BASE_UPGRADE";top.loc[normal_positive,"denominator_category"]="NORMAL_POSITIVE_UPGRADE";top["runup_category"]=top.prior_runup_pct.ge(.80).map({True:"HIGH_PRIOR_RUNUP",False:"NORMAL_PRIOR_RUNUP"});top["small_positive_cutoff"]=small_cut;selected.append(top)
 rows=pd.concat(selected,ignore_index=True);rows.to_csv(out_rows,index=False,date_format="%Y-%m-%d");total_active=float(rows.active20.sum());categories={name:summarize(g,total_active) for name,g in rows.groupby("denominator_category")};runup={name:summarize(g,total_active) for name,g in rows.groupby("runup_category")};cross={f"{a}|{b}":summarize(g,total_active) for (a,b),g in rows.groupby(["denominator_category","runup_category"])};payload={"study":"a-share-eps-denominator-attribution-v1","selected_rows":len(rows),"enabled_months":int(rows.signal_date.nunique()),"category_exact_cover":sum(v["count"] for v in categories.values())==len(rows),"denominator_categories":categories,"prior_runup":runup,"cross":cross,"limitations":["signal-level future active returns, not exact portfolio PnL attribution","historical sample already observed"]};Path(out_json).write_text(json.dumps(payload,ensure_ascii=False,indent=2)+"\n");lines=["# EPS比例修正分母与提前上涨归因","",f"- selected rows/months: {len(rows)} / {rows.signal_date.nunique()}","","## 分母类别","","|类别|记录|未来active均值|中位数|胜率|最佳5%剔除均值|","|---|---:|---:|---:|---:|---:|"]+[f"|{name}|{v['count']}|{v['future_active20_mean']:.2%}|{v['future_active20_median']:.2%}|{v['future_active20_win_rate']:.2%}|{v['trim_best5_mean']:.2%}|" for name,v in categories.items()]+["","## 提前上涨","","|类别|记录|过去active中位|未来active均值|中位数|胜率|","|---|---:|---:|---:|---:|---:|"]+[f"|{name}|{v['count']}|{v['prior_active20_median']:.2%}|{v['future_active20_mean']:.2%}|{v['future_active20_median']:.2%}|{v['future_active20_win_rate']:.2%}|" for name,v in runup.items()];Path(out_md).write_text("\n".join(lines)+"\n");print("\n".join(lines));return payload
def main(argv=None):
 p=argparse.ArgumentParser();p.add_argument("--signals",default="overall/a-share-analyst-ratio-attribution-signals.csv");p.add_argument("--rows",default="overall/a-share-eps-denominator-attribution-rows.csv");p.add_argument("--out-json",default="overall/a-share-eps-denominator-attribution.json");p.add_argument("--out-md",default="overall/a-share-eps-denominator-attribution.md");a=p.parse_args(argv);run(a.signals,a.rows,a.out_json,a.out_md);return 0
if __name__=="__main__":raise SystemExit(main())
